-- Read-only post-check for 20270102070000_editions_branding.sql. Every row should say ok = true.
select 'cover_focus exists on both tables' as check, count(*) = 2 as ok from information_schema.columns where table_schema = 'public' and table_name in ('edition_organisers','editions') and column_name = 'cover_focus';
select 'cover_focus has its shape check' as check, count(*) = 2 as ok from pg_constraint where conrelid in ('public.edition_organisers'::regclass, 'public.editions'::regclass) and contype = 'c' and pg_get_constraintdef(oid) like '%cover_focus%';
select 'only organiser administrators write it (column-level update grant, no anon)' as check, count(*) = 0 as ok from information_schema.column_privileges where table_schema = 'public' and table_name in ('edition_organisers','editions') and column_name = 'cover_focus' and grantee = 'anon' and privilege_type in ('INSERT','UPDATE');
select 'no stray values (all null or a valid pair)' as check, (select count(*) from public.edition_organisers where cover_focus is not null and cover_focus !~ '^(100|[0-9]{1,2})% (100|[0-9]{1,2})%$') + (select count(*) from public.editions where cover_focus is not null and cover_focus !~ '^(100|[0-9]{1,2})% (100|[0-9]{1,2})%$') = 0 as ok;
